mapper.select:
WITH recent_approvals AS ( SELECT approval.approval_id, approval.user_card_id, approval.merchant_name, approval.amount, approval.approved_at FROM card_payment_approvals approval INNER JOIN user_cards owned_card ON owned_card.user_card_id = approval.user_card_id WHERE owned_card.user_id = #{userId} AND approval.approved_at >= #{fromUtc} AND approval.approved_at < #{toUtc}
AND approval.user_card_id = #{userCardId}
ORDER BY approval.approved_at DESC, approval.approval_id DESC LIMIT #{limit} ), usage_summary AS ( SELECT benefit_usage.approval_id, MIN(benefit_usage.usage_id) AS benefit_history_id, SUM(CASE WHEN benefit_usage.reward_original_unit = 'point' THEN COALESCE(benefit_usage.reward_original_value, 0) ELSE benefit_usage.reward_amount_krw END) AS benefit_amount, CASE WHEN COUNT(DISTINCT CASE WHEN benefit_usage.reward_original_unit = 'mile' THEN 'MILEAGE' WHEN offer.reward_type = 'discount' THEN 'DISCOUNT' WHEN offer.reward_type = 'cashback' THEN 'CASHBACK' WHEN offer.reward_type = 'points' THEN 'POINT' END) > 1 THEN 'MULTIPLE' ELSE MAX(CASE WHEN benefit_usage.reward_original_unit = 'mile' THEN 'MILEAGE' WHEN offer.reward_type = 'discount' THEN 'DISCOUNT' WHEN offer.reward_type = 'cashback' THEN 'CASHBACK' WHEN offer.reward_type = 'points' THEN 'POINT' END) END AS benefit_type, GROUP_CONCAT(DISTINCT COALESCE(offer.offer_name, benefit.title) ORDER BY COALESCE(offer.offer_name, benefit.title) SEPARATOR ', ') AS benefit_title FROM user_benefit_usages benefit_usage INNER JOIN recent_approvals recent ON recent.approval_id = benefit_usage.approval_id INNER JOIN benefit_offers offer ON offer.offer_id = benefit_usage.offer_id INNER JOIN card_benefits benefit ON benefit.benefit_id = offer.benefit_id WHERE benefit_usage.usage_status = 'confirmed' GROUP BY benefit_usage.approval_id ), outcome_summary AS ( SELECT outcome.approval_id, MIN(outcome.outcome_id) AS benefit_history_id, SUM(CASE WHEN outcome.reward_unit = 'KRW' THEN outcome.missed_reward_value ELSE 0 END) AS missed_benefit_amount, CASE WHEN COUNT(DISTINCT CASE WHEN outcome.reward_unit = 'mile' THEN 'MILEAGE' WHEN offer.reward_type = 'discount' THEN 'DISCOUNT' WHEN offer.reward_type = 'cashback' THEN 'CASHBACK' WHEN offer.reward_type = 'points' THEN 'POINT' END) > 1 THEN 'MULTIPLE' ELSE MAX(CASE WHEN outcome.reward_unit = 'mile' THEN 'MILEAGE' WHEN offer.reward_type = 'discount' THEN 'DISCOUNT' WHEN offer.reward_type = 'cashback' THEN 'CASHBACK' WHEN offer.reward_type = 'points' THEN 'POINT' END) END AS benefit_type, GROUP_CONCAT(DISTINCT COALESCE(offer.offer_name, benefit.title) ORDER BY COALESCE(offer.offer_name, benefit.title) SEPARATOR ', ') AS benefit_title, GROUP_CONCAT(DISTINCT outcome.rejection_reason ORDER BY outcome.rejection_reason SEPARATOR ',') AS rejection_reason FROM user_benefit_calculation_outcomes outcome INNER JOIN recent_approvals recent ON recent.approval_id = outcome.approval_id INNER JOIN benefit_offers offer ON offer.offer_id = outcome.offer_id INNER JOIN card_benefits benefit ON benefit.benefit_id = offer.benefit_id WHERE outcome.outcome_status IN ('partially_applied', 'not_applied') GROUP BY outcome.approval_id ) SELECT approval.approval_id, COALESCE(benefit_usage.benefit_history_id, outcome.benefit_history_id) AS benefit_history_id, approval.merchant_name, COALESCE(benefit_usage.benefit_type, outcome.benefit_type) AS benefit_type, COALESCE(benefit_usage.benefit_title, outcome.benefit_title) AS benefit_title, COALESCE(cv.name, uc.card_name_from_codef) AS card_name, approval.amount AS payment_amount, COALESCE(benefit_usage.benefit_amount, 0) AS benefit_amount, COALESCE(outcome.missed_benefit_amount, 0) AS missed_benefit_amount, CASE WHEN benefit_usage.approval_id IS NOT NULL AND outcome.approval_id IS NOT NULL THEN 'PARTIALLY_APPLIED' WHEN benefit_usage.approval_id IS NOT NULL THEN 'APPLIED' WHEN outcome.approval_id IS NOT NULL THEN 'NOT_APPLIED' ELSE 'NOT_CALCULATED' END AS calculation_status, outcome.rejection_reason, approval.approved_at AS occurred_at FROM recent_approvals approval INNER JOIN user_cards uc ON uc.user_card_id = approval.user_card_id INNER JOIN cards c ON c.card_id = uc.card_id LEFT JOIN card_content_versions cv ON cv.card_id = c.card_id AND NOT EXISTS ( SELECT 1 FROM card_content_versions cv2 WHERE cv2.card_id = cv.card_id AND (cv2.last_seen_at > cv.last_seen_at OR (cv2.last_seen_at = cv.last_seen_at AND cv2.content_version_id > cv.content_version_id)) ) LEFT JOIN usage_summary benefit_usage ON benefit_usage.approval_id = approval.approval_id LEFT JOIN outcome_summary outcome ON outcome.approval_id = approval.approval_id ORDER BY approval.approved_at DESC, approval.approval_id DESC
